import{_ as s,o as t,c as a,ag as o}from"./chunks/framework.B7PviQjB.js";const i="/docs/images/developers/cli-login-confirm.png",g=JSON.parse('{"title":"Install and sign in","description":"Install the wafflebase command-line tool, sign in to your workspace, and set the options every command shares.","frontmatter":{"title":"Install and sign in","description":"Install the wafflebase command-line tool, sign in to your workspace, and set the options every command shares.","type":"how-to"},"headers":[],"relativePath":"developers/cli/index.md","filePath":"developers/cli/index.md"}'),d={name:"developers/cli/index.md"};function n(l,e,r,c,h,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="install-and-sign-in" tabindex="-1">Install and sign in <a class="header-anchor" href="#install-and-sign-in" aria-label="Permalink to &quot;Install and sign in&quot;">​</a></h1><p>Install the <code>wafflebase</code> command-line tool, sign in, and pick the workspace your commands run against.</p><p>The CLI reads and edits the same documents you open in the browser: sheets, docs, decks, notes, boards, and stored files. Every command prints JSON by default, so you can pipe it into <code>jq</code>, a script, or an agent.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Node.js 20.18.1 or later.</li><li>A Wafflebase account. To use your own server, you need its API URL, for example <code>https://api.example.com</code>.</li></ul></div><h2 id="install-the-cli" tabindex="-1">Install the CLI <a class="header-anchor" href="#install-the-cli" aria-label="Permalink to &quot;Install the CLI&quot;">​</a></h2><ol><li><p>Install the package globally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @wafflebase/cli</span></span></code></pre></div></li><li><p>Check that it runs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div></li></ol><p>The command prints the CLI version.</p><p>To pin the CLI to one project instead, install it as a dev dependency with <code>npm install -D @wafflebase/cli</code> and run it with <code>npx wafflebase</code>.</p><h2 id="sign-in-with-your-browser" tabindex="-1">Sign in with your browser <a class="header-anchor" href="#sign-in-with-your-browser" aria-label="Permalink to &quot;Sign in with your browser&quot;">​</a></h2><ol><li><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>To sign in to your own server, add its API URL: <code>wafflebase login --server https://api.example.com</code>. <code>login</code> reads only the flag, not <code>WAFFLEBASE_SERVER</code>; later commands use the server you signed in to.</p></li><li><p>Your browser opens a page titled <strong>Continue signing in to the Wafflebase CLI?</strong> Click <strong>Continue</strong>.</p></li><li><p>Sign in with GitHub if the browser asks you to.</p></li><li><p>Back in the terminal, if you belong to more than one workspace, type the number of the one to use and press <code>Enter</code>.</p></li></ol><p>The terminal prints <code>Logged in as &lt;username&gt;.</code> The session is saved in <code>~/.wafflebase/session.json</code> and refreshes itself when it expires. The browser has 5 minutes to finish the sign-in.</p><p><img src="'+i+`" alt="Browser page asking to continue signing in to the Wafflebase CLI, with a Continue button"></p><p>The CLI also prints the sign-in URL, so you can open it yourself if no browser appears. When the output isn&#39;t a terminal, such as in a CI log, it writes the URL to a private file and prints that file&#39;s path instead. Don&#39;t share the URL: it carries one-time secrets.</p><h3 id="check-who-you-are-signed-in-as" tabindex="-1">Check who you are signed in as <a class="header-anchor" href="#check-who-you-are-signed-in-as" aria-label="Permalink to &quot;Check who you are signed in as&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>The output has <code>loggedIn</code>, <code>auth</code>, <code>user</code>, <code>email</code>, <code>server</code>, <code>workspaceId</code>, <code>workspaceName</code>, <code>session</code> (<code>valid</code> or <code>expired</code>), and <code>expiresAt</code>. An expired session refreshes itself on the next command. <code>loggedIn</code> says whether a browser session exists; <code>auth</code> says what your commands actually use — <code>session</code>, <code>api-key</code> (an API key wins over the session, and <code>workspaceId</code> is then the key&#39;s workspace) or <code>none</code>.</p><h3 id="sign-out" tabindex="-1">Sign out <a class="header-anchor" href="#sign-out" aria-label="Permalink to &quot;Sign out&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logout</span></span></code></pre></div><p>This deletes the saved session.</p><h3 id="sign-in-to-an-older-server" tabindex="-1">Sign in to an older server <a class="header-anchor" href="#sign-in-to-an-older-server" aria-label="Permalink to &quot;Sign in to an older server&quot;">​</a></h3><p><code>--allow-unbound-callback</code> lets <code>wafflebase login</code> finish against a self-hosted server too old to support the current sign-in check. While it is on, the CLI accepts any sign-in callback without checking that it belongs to this login, so a program on your computer, or a web page you open while the login waits, can finish it with a sign-in of its choosing and leave you signed in as someone else. The CLI prints a warning when you use it. Upgrade the server instead when you can.</p><h2 id="switch-workspaces" tabindex="-1">Switch workspaces <a class="header-anchor" href="#switch-workspaces" aria-label="Permalink to &quot;Switch workspaces&quot;">​</a></h2><ol><li><p>List the workspaces you belong to:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ctx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> table</span></span></code></pre></div></li><li><p>Switch by name or ID:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ctx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Marketing&quot;</span></span></code></pre></div></li></ol><p>The name must match exactly, ignoring case. You can also pass a full workspace ID, or the start of one if only one workspace ID starts that way. <code>ctx</code> works only with a browser session. To run a single command in another workspace without switching, add <code>--workspace &lt;id&gt;</code>.</p><h2 id="use-an-api-key-instead" tabindex="-1">Use an API key instead <a class="header-anchor" href="#use-an-api-key-instead" aria-label="Permalink to &quot;Use an API key instead&quot;">​</a></h2><p>Use an API key in scripts and CI, where no browser is available. A key belongs to one workspace, so always pass the workspace ID with it.</p><ol><li><p>Create a key in the web app under <strong>Settings &gt; API keys &gt; Create API key</strong>, or run <code>wafflebase api-keys create &quot;CI&quot;</code> while signed in. See <a href="/docs/developers/cli/automation.html#create-and-revoke-api-keys">Automation and agents</a>.</p></li><li><p>Export it with the workspace ID or slug. The slug is the part after <code>/w/</code> in the web app&#39;s address.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WAFFLEBASE_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wfb_your_key</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WAFFLEBASE_WORKSPACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your-workspace-id</span></span></code></pre></div></li><li><p>Run a command to check it works:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div></li></ol><p>A key from <code>--api-key</code> or <code>WAFFLEBASE_API_KEY</code> wins over a saved browser session. A few commands need the browser session and refuse a key: <code>api-keys</code>, <code>bots</code>, <code>templates publish</code>, <code>templates use</code>, and <code>slides render</code>. The <code>agent</code> commands use only a bot&#39;s stored key; see <a href="/docs/developers/bots.html#keep-its-key-safe">Put a bot to work</a>.</p><div class="danger custom-block"><p class="custom-block-title">Keep API keys secret</p><p>A key acts as the member who created it, with read and write access to that workspace. Store it in your CI secret store, never in a repository. Revoke a leaked key with <code>wafflebase api-keys revoke &lt;key-id&gt;</code>.</p></div><h2 id="save-settings-in-a-profile" tabindex="-1">Save settings in a profile <a class="header-anchor" href="#save-settings-in-a-profile" aria-label="Permalink to &quot;Save settings in a profile&quot;">​</a></h2><p>Put settings you reuse in <code>~/.wafflebase/config.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">profiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.wafflebase.io</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    workspace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-workspace-id</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  selfhosted</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">wfb_your_key</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    workspace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">another-workspace-id</span></span></code></pre></div><p>Pick a profile with <code>--profile</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> selfhosted</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>The CLI picks its credentials in this order, first match wins:</p><ol><li>An API key from <code>--api-key</code> or <code>WAFFLEBASE_API_KEY</code>.</li><li>The saved browser session from <code>wafflebase login</code>.</li><li>The profile&#39;s <code>api-key</code>.</li></ol><p>The server and workspace come from the command-line flag, then the environment variable, then the saved browser session, then the profile.</p><div class="info custom-block"><p class="custom-block-title">A browser session hides a profile&#39;s API key</p><p>While you are signed in, <code>--profile selfhosted</code> still uses your browser session and its server. To use the profile&#39;s key, run <code>wafflebase logout</code> first, or pass the key with <code>WAFFLEBASE_API_KEY</code>.</p></div><table tabindex="0"><thead><tr><th>Variable</th><th>What it sets</th></tr></thead><tbody><tr><td><code>WAFFLEBASE_SERVER</code></td><td>API server URL. Default: <code>https://api.wafflebase.io</code>.</td></tr><tr><td><code>WAFFLEBASE_API_KEY</code></td><td>API key. When set, it is used instead of the browser session.</td></tr><tr><td><code>WAFFLEBASE_WORKSPACE</code></td><td>Workspace ID.</td></tr><tr><td><code>WAFFLEBASE_CONFIG</code></td><td>Path of the config file, in place of <code>~/.wafflebase/config.yaml</code>.</td></tr><tr><td><code>WAFFLEBASE_SESSION</code></td><td>Path of the saved browser session, in place of <code>~/.wafflebase/session.json</code>.</td></tr><tr><td><code>WAFFLEBASE_FRONTEND_URL</code></td><td>Web app URL for <code>slides render</code>, when it can&#39;t be worked out from the server.</td></tr></tbody></table><h2 id="global-options" tabindex="-1">Global options <a class="header-anchor" href="#global-options" aria-label="Permalink to &quot;Global options&quot;">​</a></h2><p>These options work on every command. Put them before or after the command name.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>--server &lt;url&gt;</code></td><td>API server URL</td><td><code>https://api.wafflebase.io</code></td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>API key</td><td>none</td></tr><tr><td><code>--workspace &lt;id&gt;</code></td><td>Workspace ID</td><td>the active workspace</td></tr><tr><td><code>--profile &lt;name&gt;</code></td><td>Profile in the config file</td><td><code>default</code></td></tr><tr><td><code>--format &lt;fmt&gt;</code></td><td>Output format: <code>json</code>, <code>table</code>, <code>csv</code>, or <code>yaml</code></td><td><code>json</code></td></tr><tr><td><code>--quiet</code></td><td>Hide progress notices. Results and errors still print.</td><td>off</td></tr><tr><td><code>--verbose</code></td><td>Print more detail</td><td>off</td></tr><tr><td><code>--dry-run</code></td><td>Print the request instead of sending it</td><td>off</td></tr><tr><td><code>-V</code>, <code>--version</code></td><td>Print the CLI version</td><td></td></tr><tr><td><code>--help</code></td><td>Show help for any command, for example <code>wafflebase sheets cells --help</code></td><td></td></tr></tbody></table><p><code>--format</code> also takes <code>md</code> and <code>text</code> on the <code>content</code> commands, and <code>pdf</code>, <code>docx</code>, <code>pptx</code>, or <code>md</code> on the <code>export</code> commands. See each command for what it accepts.</p><h2 id="command-namespaces" tabindex="-1">Command namespaces <a class="header-anchor" href="#command-namespaces" aria-label="Permalink to &quot;Command namespaces&quot;">​</a></h2><p>Commands are grouped by what they act on. Singular forms work as aliases, so <code>wafflebase doc list</code> is the same as <code>wafflebase docs list</code>.</p><table tabindex="0"><thead><tr><th>Namespace</th><th>Aliases</th><th>What it does</th><th>Reference</th></tr></thead><tbody><tr><td><code>docs</code></td><td><code>doc</code>, <code>document</code>, <code>documents</code></td><td>List, create, copy, move, and delete any document; read, import, and export docs</td><td><a href="/docs/developers/cli/documents.html">Documents and notes</a></td></tr><tr><td><code>notes</code></td><td><code>note</code></td><td>Markdown notes</td><td><a href="/docs/developers/cli/documents.html#notes">Documents and notes</a></td></tr><tr><td><code>folders</code></td><td><code>folder</code></td><td>Workspace folders</td><td><a href="/docs/developers/cli/documents.html#folders">Documents and notes</a></td></tr><tr><td><code>comments</code></td><td><code>comment</code></td><td>Comment threads</td><td><a href="/docs/developers/cli/documents.html#comments">Documents and notes</a></td></tr><tr><td><code>templates</code></td><td><code>template</code></td><td>Browse, publish, and use templates</td><td><a href="/docs/developers/cli/documents.html#templates">Documents and notes</a></td></tr><tr><td><code>sheets</code></td><td><code>sheet</code>, <code>spreadsheet</code>, <code>spreadsheets</code></td><td>Tabs, cells, rows and columns, formatting, charts</td><td><a href="/docs/developers/cli/sheets.html">Sheets</a></td></tr><tr><td><code>slides</code></td><td><code>slide</code>, <code>deck</code></td><td>Decks, slides, import and export, lint and render</td><td><a href="/docs/developers/cli/slides-and-board.html">Slides and boards</a></td></tr><tr><td><code>board</code></td><td><code>boards</code></td><td>Board elements, stickies, sections</td><td><a href="/docs/developers/cli/slides-and-board.html#boards">Slides and boards</a></td></tr><tr><td><code>files</code></td><td><code>file</code></td><td>Store any file as a document</td><td><a href="/docs/developers/cli/files-and-images.html">Files and images</a></td></tr><tr><td><code>images</code></td><td><code>image</code></td><td>Workspace images that documents embed</td><td><a href="/docs/developers/cli/files-and-images.html#workspace-images">Files and images</a></td></tr><tr><td><code>api-keys</code></td><td><code>api-key</code></td><td>Create, list, and revoke API keys</td><td><a href="/docs/developers/cli/automation.html#create-and-revoke-api-keys">Automation and agents</a></td></tr><tr><td><code>bots</code></td><td><code>bot</code></td><td>Create, list, and delete workspace bots; get a pairing code</td><td><a href="/docs/developers/bots.html">Put a bot to work</a></td></tr><tr><td><code>agent</code></td><td></td><td>Connect this computer to a bot and answer its tasks</td><td><a href="/docs/developers/bots.html#commands">Put a bot to work</a></td></tr><tr><td><code>schema</code></td><td></td><td>Describe any command&#39;s parameters and output</td><td><a href="/docs/developers/cli/automation.html#look-up-a-command-with-schema">Automation and agents</a></td></tr><tr><td><code>login</code>, <code>logout</code>, <code>status</code>, <code>ctx</code></td><td></td><td>Sign-in and workspace selection</td><td>This page</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/developers/cli/documents.html">Documents and notes</a> to list, create, and convert documents.</li><li><a href="/docs/developers/cli/sheets.html">Sheets</a> to read and write cells from a script.</li><li><a href="/docs/developers/cli/automation.html">Automation and agents</a> for output formats, errors, and exit codes.</li><li><a href="/docs/developers/claude-code-plugin.html">Claude Code plugin</a> to let Claude run these commands for you.</li><li><a href="/docs/developers/self-hosting/sign-in.html">Sign-in providers</a> if CLI sign-in fails on your own server.</li></ul>`,48)])])}const u=s(d,[["render",n]]);export{g as __pageData,u as default};
